function renderIrrigationLoxoneGuide(){const target=$('irrigationLoxoneGuide');if(!target)return;const base=location.origin,fields=[['Temperature','temperature','°C'],['Relative humidity','humidity','%'],['Pressure','pressure','hPa'],['Wind speed','wind','km/h'],['Light level','light','lux'],['Rainfall','rainfall','cumulative mm counter']];const zones=cfg.irrigation?.zones||[];target.innerHTML=`<p>Use these GET commands in an HTTP Virtual Output. Substitute the matching Loxone sensor value for <code>&lt;value&gt;</code>. Send all six fields, then commit once for that sample. Values are staged until commit; a successful commit clears the staging area.</p><p class="irrigation-base-url">Gateway base URL: <code>${esc(base)}</code></p><div class="table-wrap"><table><thead><tr><th>Input</th><th>Command URL</th><th>Units / meaning</th></tr></thead><tbody>${fields.map(([label,key,unit])=>`<tr><td>${esc(label)}</td><td><code>${esc(base)}/Irrigation/weather/${key}/&lt;value&gt;</code></td><td>${esc(unit)}</td></tr>`).join('')}<tr><td>Commit sample</td><td><code>${esc(base)}/Irrigation/weather/commit</code></td><td>Call after all six fields</td></tr></tbody></table></div><p><strong>Read from gateway:</strong> wire the following as HTTP Virtual Inputs as needed. Zone runtime is seconds. Other values are numeric; rain, ET0, deficit, and wetness are mm.</p><div class="table-wrap"><table><thead><tr><th>Signal</th><th>GET URL</th><th>Meaning</th></tr></thead><tbody><tr><td>Irrigate</td><td><code>${esc(base)}/Irrigation/irrigate</code></td><td>1 if any zone has a non-zero runtime</td></tr>${zones.map(z=>`<tr><td>${esc(z.loxoneName||z.id||'Unconfigured zone')} runtime</td><td><code>${esc(base)}/Irrigation/zone/${encodeURIComponent(z.id||'<zone-id>')}</code></td><td>Recommended runtime in seconds</td></tr>`).join('')}<tr><td>Data complete</td><td><code>${esc(base)}/Irrigation/data-complete</code></td><td>Recent 24-hour observation coverage diagnostic</td></tr><tr><td>Forecast rain</td><td><code>${esc(base)}/Irrigation/forecast-rain</code></td><td>Forecast rain over configured horizon</td></tr><tr><td>Deficit</td><td><code>${esc(base)}/Irrigation/deficit</code></td><td>Highest stored balance-group deficit</td></tr><tr><td>Mowing allowed</td><td><code>${esc(base)}/Irrigation/mowing-allowed</code></td><td>1 only when mowing checks pass</td></tr></tbody></table></div><p><strong>Automatic run tracking:</strong> select and import an Irrigation function block above. The gateway tracks a zone only when the block's live <code>active</code> state is true and <code>currentZone</code> identifies it; no per-zone run-reporting commands are required. Zone type, balance group, exposure and application rate remain gateway settings.</p>`;renderIrrigationBlockImporter()}
let irrigationBlocks=[];
async function renderIrrigationBlockImporter(){const target=$('irrigationLoxoneGuide');if(!target)return;let shell=$('irrigationBlockImporter');if(!shell){target.insertAdjacentHTML('afterbegin',`<section id="irrigationBlockImporter" class="irrigation-live"><h3>Import zones from a Loxone Irrigation block</h3><p class="notice">Select a discovered block, preview its live zone list, then import. Imported Loxone IDs/names are stored separately from gateway zone IDs; existing water-balance history and zone settings are retained.</p><div class="row"><select id="irrigationBlockSelect" aria-label="Irrigation function block"><option value="">Loading irrigation blocks…</option></select><button type="button" class="secondary" id="refreshIrrigationBlocks">Refresh blocks</button><button type="button" id="previewIrrigationBlock">Preview</button></div><div id="irrigationBlockResult" class="notice" role="status" aria-live="polite"></div></section>`);shell=$('irrigationBlockImporter')}const select=$('irrigationBlockSelect'),refresh=$('refreshIrrigationBlocks'),previewButton=$('previewIrrigationBlock'),result=$('irrigationBlockResult'),saved=cfg.irrigation?.loxoneBlock;refresh.onclick=()=>loadIrrigationBlocks();previewButton.onclick=async()=>{const blockId=select.value;if(!blockId){result.textContent='Choose a discovered block first.';return}previewButton.disabled=true;result.textContent='Reading live block states…';try{const data=await api('irrigation/loxone/preview',{method:'POST',body:JSON.stringify({blockId})});result.innerHTML=`<p>Current zone index: <code>${data.currentZone}</code> (${data.currentZone===-1?'off':data.currentZone===8?'all zones active':esc(data.zones[data.currentZone]?.name||'zone '+(data.currentZone+1))}). Import will add or update ${data.zones.length} zone(s); omitted previously imported zones will be retained.</p><div class="table-wrap"><table><thead><tr><th>Loxone ID</th><th>Name</th><th>Configured duration</th></tr></thead><tbody>${data.zones.map(z=>`<tr><td><code>${esc(z.loxoneZoneId)}</code></td><td>${esc(z.name)}</td><td>${z.durationSeconds}s</td></tr>`).join('')}</tbody></table></div><button type="button" id="importIrrigationBlock">Import zones</button>`;$('importIrrigationBlock').onclick=async()=>{const button=$('importIrrigationBlock');button.disabled=true;try{await api('irrigation/loxone/import',{method:'POST',body:JSON.stringify({blockId})});await load();renderIrrigationLoxoneGuide();showInfoToast('Loxone irrigation zones imported. Review type, balance group, exposure and application rate before use.','success')}catch(e){result.textContent=e.message;button.disabled=false}}}catch(e){result.textContent=e.message}finally{previewButton.disabled=false}};await loadIrrigationBlocks();}
async function loadIrrigationBlocks(){const select=$('irrigationBlockSelect'),refresh=$('refreshIrrigationBlocks'),result=$('irrigationBlockResult');if(!select)return;refresh.disabled=true;select.disabled=true;result.textContent='Loading irrigation blocks…';try{irrigationBlocks=await api('irrigation/loxone/blocks');const saved=cfg.irrigation?.loxoneBlock;select.innerHTML='<option value="">Choose an irrigation block</option>'+irrigationBlocks.map(b=>`<option value="${esc(b.id)}" ${(saved&&saved.serverId===b.serverId&&saved.control===b.control)?'selected':''}>${esc(b.serverName)} · ${esc(b.control)}</option>`).join('');if(!irrigationBlocks.length){select.innerHTML='<option value="">No compatible blocks found — refresh Loxone resources first</option>';result.textContent='No discovered block has an active state, current zone, and zone list.'}else result.textContent='Select a block and preview its live zone list.'}catch(e){select.innerHTML='<option value="">Unable to load irrigation blocks</option>';result.textContent=`Could not load irrigation blocks: ${e.message}`}finally{refresh.disabled=false;select.disabled=false}}
